<script setup>
// News centre (list + detail). Articles, categories and featured flags come from the news API, backed by the shared
// news module that the admin 内容管理 manages (static in-page mock, user decision 2026-11-27). One article carries all
// six languages, so switching language keeps the same article; old per-language ids and home aliases still resolve.
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {locale,t} from '../i18n'
import {path} from '../data'
import RequestState from '../components/ui/RequestState.vue'
import {useRequest} from '../composables/useRequest.js'
import {getNewsArticle,listNewsArticles} from '../api/news.js'
import {relativeTime} from '../utils/newsTime.js'
import {sanitizeHtml} from '../../../src/shared/news/html.js'
const route=useRoute(),router=useRouter(),category=ref('all'),limit=ref(10)
const id=computed(()=>route.params.id||'')
const listRequest=useRequest(()=>listNewsArticles(locale.value),{key:()=>locale.value})
const articleRequest=useRequest(()=>getNewsArticle(id.value,locale.value),{key:()=>id.value&&[id.value,locale.value].join('|'),immediate:!!id.value})
const articles=computed(()=>listRequest.data.value?.articles||[]),categories=computed(()=>listRequest.data.value?.categories||[])
// A category the admin disabled drops out of the filter; fall back to all.
watch(categories,list=>{if(category.value!=='all'&&!list.some(c=>c.categoryId===category.value))category.value='all'})
const filtered=computed(()=>articles.value.filter(n=>category.value==='all'||n.category===category.value)),visible=computed(()=>filtered.value.slice(0,limit.value))
watch(category,()=>limit.value=10)
const article=computed(()=>id.value?articleRequest.data.value:null),notFound=computed(()=>articleRequest.error.value?.code==='notFound')
// Canonical URL: an old per-language id or home alias is replaced by the article id.
watch(article,a=>{if(a&&id.value&&a.articleId!==id.value)router.replace(path('/news/'+a.articleId))})
const meta=n=>[n.source?.name,relativeTime(n.publishedAt,locale.value),n.categoryName].filter(Boolean).join(' · ')
const sourceHome=url=>{try{return new URL(url).origin+'/'}catch{return ''}}
</script>
<template><template v-if="!id"><header class="news-heading grid-background"><nav><RouterLink :to="path('/')">{{t('news.breadcrumbHome')}}</RouterLink><span>/</span>{{t('news.breadcrumbNews')}}</nav><h1>{{t('news.pageTitle')}}</h1></header><section class="news-feed"><RequestState v-if="listRequest.status.value==='error'" :status="listRequest.status.value" :error="listRequest.error.value" @retry="listRequest.refresh"/><p v-else-if="listRequest.status.value==='loading'" class="mini-label center" role="status">{{t('news.loading')}}</p><template v-else><div class="news-filters"><button :class="{active:category==='all'}" :aria-pressed="category==='all'" @click="category='all'">{{t('news.categoryAll')}}</button><button v-for="c in categories" :key="c.categoryId" :class="{active:category===c.categoryId}" :aria-pressed="category===c.categoryId" @click="category=c.categoryId">{{c.name}}</button></div><RouterLink v-for="n in visible" :key="n.articleId" class="news-item" :to="path('/news/'+n.articleId)"><img decoding="async" v-if="n.image" :src="n.image" alt="" loading="lazy"/><div><small>{{meta(n)}}</small><h3>{{n.title}}</h3><p>{{n.summary}}</p><div v-if="n.tags.length" class="news-tags"><span v-for="tag in n.tags" :key="tag">{{tag}}</span></div><span class="sr-only">{{t('news.readTime',{minutes:3})}}</span></div></RouterLink><div v-if="!visible.length" class="empty"><h2>{{t('news.emptyTitle')}}</h2><p>{{t('news.emptyHint')}}</p></div><button v-if="limit<filtered.length" class="secondary-button load-more" @click="limit+=10">{{t('news.loadMore')}}</button><p v-else-if="visible.length" class="mini-label center">{{t('news.noMore')}}</p></template></section></template><template v-else-if="article"><header class="news-heading article-heading"><nav><RouterLink :to="path('/')">{{t('news.breadcrumbHome')}}</RouterLink><span>/</span><RouterLink :to="path('/news')">{{t('news.breadcrumbNews')}}</RouterLink><span>/</span><span>{{article.title}}</span></nav><h1>{{article.title}}</h1><p class="article-meta"><span v-if="article.source?.name">{{article.source.name}}</span><span>{{t('news.publishedAt')}} {{relativeTime(article.publishedAt,locale)}}</span><span v-if="article.categoryName">{{article.categoryName}}</span></p></header><article class="article-content"><p class="article-lead">{{article.summary}}</p><!-- Body is the admin editor's HTML, cleaned again to the allow-list before rendering. -->
<div v-if="article.body" class="article-body" v-html="sanitizeHtml(article.body)"></div><div v-if="article.source?.url" class="article-links"><a class="green-link" :href="article.source.url" target="_blank" rel="noopener">{{t('news.viewOriginal')}}</a><a v-if="sourceHome(article.source.url)" :href="sourceHome(article.source.url)" class="muted" target="_blank" rel="noopener">{{t('news.viewSource')}}</a></div><RouterLink :to="path('/news')" class="green-link">{{t('news.backToList')}}</RouterLink></article></template><section v-else-if="notFound" class="empty news-missing"><h1>{{t('news.articleNotFound')}}</h1><RouterLink class="primary-button" :to="path('/news')">{{t('news.backToList')}}</RouterLink></section><section v-else-if="articleRequest.status.value==='error'" class="news-feed"><RequestState :status="articleRequest.status.value" :error="articleRequest.error.value" @retry="articleRequest.refresh"/></section><p v-else class="mini-label center news-missing" role="status">{{t('news.loading')}}</p></template>
<style scoped>.news-heading{padding:96px 24px;border-bottom:1px solid #ffffff12}.news-heading>*{max-width:1352px;margin-left:auto;margin-right:auto}.news-heading nav>span{min-width:0;overflow-wrap:anywhere}.news-heading nav{display:flex;gap:12px;flex-wrap:wrap;color:#fff9;font:12px/16px 'IBM Plex Mono',monospace;margin-bottom:24px}.news-heading h1{overflow-wrap:anywhere;font-size:3rem;line-height:1;letter-spacing:-1px}.grid-background{background:radial-gradient(ellipse at 50% 0,#bdff0006,transparent 70%),linear-gradient(90deg,#ffffff08 1px,transparent 1px),linear-gradient(#ffffff08 1px,transparent 1px);background-size:auto,56px 56px,56px 56px}.news-feed{max-width:1400px;margin:auto;padding:32px 24px 64px}.news-filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:64px}.news-filters button{padding:6px 16px;line-height:20px;border:1px solid #ffffff12;border-radius:99px;font-size:0.875rem}.news-filters .active{background:#c2ff0012;color:var(--nt-accent);border-color:#c2ff0040}.news-item{display:flex;gap:24px;padding:24px;margin-bottom:24px;border:1px solid transparent;border-radius:var(--nt-radius-sm)}.news-item:hover{background:#ffffff03;border-color:#c2ff0020}.news-item img{width:176px;height:112px;object-fit:cover;border-radius:var(--nt-radius-sm);flex-shrink:0}.news-item>div{min-width:0}.news-item small{display:block;line-height:16px}.news-item small,.article-meta{color:#fff9;font:12px/16px 'IBM Plex Mono',monospace}.news-item h3{font-size:1.25rem;margin:8px 0;line-height:1.375}.news-item:hover h3{color:var(--nt-accent)}.news-item p{font-size:0.875rem;line-height:20px;color:#fff9}.news-tags{display:flex;gap:8px;margin-top:12px}.news-tags span{font:12px/16px monospace;border:1px solid #ffffff12;border-radius:var(--nt-radius-sm);padding:2px 8px;color:#fff9}.load-more{display:block;margin:32px auto}.center{text-align:center}.article-heading nav{margin-bottom:32px}.article-heading h1{line-height:1.25}.article-meta{display:flex;gap:16px;flex-wrap:wrap;margin-top:24px}.article-content{padding:64px 24px;max-width:1400px;margin:auto}.article-content>*{max-width:calc((100% - 24px)*2/3)}.article-lead{font-size:1.125rem;color:#fff9;line-height:1.8;margin-bottom:32px}.article-body{font-size:1rem;line-height:1.8;color:#fffb}.article-body :deep(p){margin:0 0 16px}.article-body :deep(h2){font-size:1.375rem;line-height:1.4;margin:32px 0 12px;color:#fff}.article-body :deep(:is(ul,ol)){padding-left:1.25rem;margin:0 0 16px}.article-body :deep(ul){list-style:disc}.article-body :deep(ol){list-style:decimal}.article-body :deep(a){color:var(--nt-accent);text-decoration:underline}.article-links{display:flex;gap:24px;margin:32px 0 48px}.news-missing{min-height:60vh}@media(max-width:700px){.news-heading{padding:48px 20px}.news-heading h1{overflow-wrap:anywhere;font-size:2rem}.news-heading>*{max-width:1352px;margin-left:auto;margin-right:auto}.news-heading nav>span{min-width:0;overflow-wrap:anywhere}.news-heading nav{margin-bottom:24px}.news-feed{padding:24px 16px 48px}.news-filters{margin-bottom:32px}.news-item{padding:16px 4px;gap:16px}.news-item img{display:none}.news-item h3{font-size:1.125rem}.article-content{padding:40px 20px}.article-content>*{max-width:100%}.article-lead{font-size:1rem}}
</style>
